#include <algorithm>
#include <cmath>
#include <iostream>
#include <iomanip>
using namespace std;
double pow2(double x){return x*x;}
int main(){double coreFraction,coreRadius,b;const double normPi=1/(2*acos(-1.)),EXPMAX=50.;
while(cin>>coreFraction>>coreRadius>>b){double fracA,fracB,fracC,radius2B,radius2C,overlapNow;
    fracA        = pow2(1. - coreFraction);
    fracB        = 2. * coreFraction * (1. - coreFraction);
    fracC        = pow2(coreFraction);
    radius2B     = 0.5 * (1. + pow2(coreRadius));
    radius2C     = pow2(coreRadius);
          overlapNow = normPi * ( fracA * exp( -min(EXPMAX, b*b))
            + fracB * exp( -min(EXPMAX, b*b / radius2B)) / radius2B
            + fracC * exp( -min(EXPMAX, b*b / radius2C)) / radius2C );
cout<<setprecision(17)<<overlapNow<<"\n";}}
